insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p116', 'allemand', '3AS', 15, 116, 'L6 3AS p116 — Adjektive ergänzen + bevor/nachdem (Üben zu zweit)', E'7. Ergänzen Sie das passende Adjektiv.\n- Reines Wasser ist …\n- Diese schwere Übung ist …\n- Dieses Schiff ist un…\n- Diese leckere Speise ist …\n- Diese Pilze sind …\n- Von deinen Vorschlägen ist leider keiner …\n- Plastik ist …\n- Diese Armbänder sind …\nBevor ich anrufen kann, muss ich…\n1. Üben Sie zu zweit wie im Beispiel.\n- Weißt du, bevor ich frühstücke, schicke ich eine SMS.\n- Ich putze meine Zähne, nachdem ich eine SMS geschickt habe.\nTabelle : frühstücken/eine SMS schicken · zur Schule gehen/eine E-Mail schreiben · Hausaufgaben machen/sich ausruhen · arbeiten/eine Freundin anrufen · eine E-Mail schreiben/den PC einschalten · Zähne putzen/eine SMS schicken · telefonieren/eine E-Mail schreiben · mit meinem Bruder sprechen/sich ausruhen · eine Freundin anrufen/etwas essen · am Computer arbeiten/ihn einschalten', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p117', 'allemand', '3AS', 15, 117, 'L6 3AS p117 — Telefon-Ablauf (bevor/nachdem/wenn) + Konjunktionen ergänzen', E'2. Sie wollen Ihren Freund / Ihre Freundin anrufen. Was müssen Sie tun ? Verwenden Sie bei der Darstellung der einzelnen Vorgänge die folgenden Konjunktionen : bevor, nachdem und wenn.\nDas Telefon : Hörer abnehmen · die Karte hineinstecken · die Tasten drücken\nA : Teilnehmer meldet sich · Sprechen · Hörer einhängen · Karte herausnehmen\nB : Teilnehmer meldet sich nicht · Hörer einhängen · Karte entnehmen\nA : Bevor ich die Karte hineinstecke, nehme ich den Hörer ab.\nB : Nachdem ich den Hörer abgenommen habe, stecke ich die Karte hinein.\n3. Ergänzen Sie die Konjunktionen. (während · wenn · als · nachdem · bevor)\n- ……… er ins Cybercafe ging, rief er seine Eltern an.\n- ……… er die verschiedenen Angebote sehr genau geprüft hatte, entschied er sich für eins.\n- ……… er auf den Zug wartete, las er die Zeitung.\n- ……… sie Chemie studierte, war sie Laborantin.\n- ……… ich langsam durch das Zoo ging, beobachtete ich die Tiere.\n- ……… die letzten Gäste sich verabschiedet hatten, war es schon Zeit zum Frühstücken.\n- ……… der alte Mann spazieren geht, begleitet ihn meist sein Hund.\n- ……… die Kinder ins Bett gehen mussten, durften sie noch etwas.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p118', 'allemand', '3AS', 15, 118, 'L6 3AS p118 — Das Internet (Text + R/F + Ergänzen + Synonyme + Antworten)', E'Das Internet\nDas Internet wird in Schule und Beruf immer wichtiger.\nÜber Internet bekommt man zahlreiche Informationen, über Internet kann man lernen, einkaufen oder Reisen buchen und und und…\nFür viele Menschen ist das Internet das Medium, das den Kontakt zu anderen möglich macht. Immer mehr junge Leute chatten. Sie kommunizieren im Internet mit Menschen, denen sie in Wirklichkeit noch nie begegnet sind. Sie unterhalten sich oft intensiv mit Personen, die sie gar nicht kennen.\nE-Mails verschicken, Suchmaschinen benutzen, chatten sind heute für die Kinder selbstverständlich geworden.\nMindestens surft ein Drittel der Kinder regelmäßig online, alleine durch das World Wide Web und das, obwohl sich viele Eltern durchaus der Gefahren des Internets bewusst sind. Im Internet finden sich leider auch Angebote, die den Nachwuchssurfern schaden können.\n1. Richtig oder falsch ? Kreuzen Sie an. (R/F)\n- Das Internet spielt kaum eine Rolle im Leben.\n- Das Internet hat viele Vorteile.\n- Das Internet gehört nicht zu den Kommunikationsmitteln.\n- Der Gebrauch des Internets ist für die Kinder gefahrlos.\n2. Ergänzen Sie. (zahlreich · sich beschäftigen · Angebote · surfen und chatten · begegnen)\n- Die Kinder müssen ………… im Internet einschätzen lernen.\n- ………… sind nicht ohne Gefahren.\n- Heute ……… die Jugendlichen ihren Mitschülern im Cybercafe.\n- Viele Kinder ………… mit Handyspielen.\n- Das Internet bietet uns ………… Dienste.\n3. Ersetzen Sie die hier unterstrichenen Wörter durch Synonyme aus dem Text.\n- Über Internet kann man Informationen zu Hause erhalten.\n- Heutzutage verfügen die Kinder über viele Computerspiele.\n- Die Jugendlichen treffen ihre Mitschüler oft im Cybercafé.\n- «Könntest du mir bitte dein Gameboy ausleihen ?» – «Aber, natürlich !»\n4. Antworten Sie.\n1. Wo wird das Internet benutzt ?\n2. Warum ist das Internet unentbehrlich ?\n3. Was ermöglicht das Internet ?\n4. Interessieren sich die Kinder für das Internet ?\n5. Für wen sind einige Angebote gefährlich ?', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p119', 'allemand', '3AS', 15, 119, 'L6 3AS p119 — Obwohl/trotzdem Konzessivsätze + Relativpronomen im Genitiv (dessen/deren)', E'Obwohl die Handykosten hoch sind, nimmt…\n1. Üben Sie wie im Beispiel.\n- Die Kosten des Handys sind hoch, trotzdem nimmt sein Gebrauch ständig zu.\n- Obwohl die Kosten des Handys hoch sind, nimmt sein Gebrauch ständig zu.\nTabelle : Das Handy/Kosten hoch · Das Internet/gefährlich · MP3-Player (Pl)/teuer · Computer (Pl)/kompliziert · Spraydosen/schädlich für die Umwelt\n2. Bilden Sie Konzessivsätze mit Obwohl.\n- Ein Computer ist teuer. Viele Leute kaufen ihn.\n- Der Gebrauch des Handys im Unterricht ist verboten. Die Schüler schalten es ein.\n- Peter hat nur ein Prepaid-Handy. Er schickt SMS tagsüber.\n- Sein Handy bietet Zugang zum mobilen Internet. Er geht oft zum Cybercafé.\n- Das Internet bietet zahlreiche Dienste. Wir müssen vorsichtig sein.\nDas Internet ist ein Medium, dessen Möglichkeiten unendlich sind…\n1. Lesen Sie und variieren Sie.\n- Gucken Sie mal ! Die Taste ist kaputt. Ich kaufe doch keinen Computer, dessen Taste kaputt ist.\nRelativpronomen im Genitiv : dessen (Maskulinum) · dessen (Neutrum) · deren (Femininum) · deren (Plural)\nTabelle : Computer/Taste · Digitalkamera/objektiv · Mobiltelefon/Display · DVD-Spieler/Taste · Radio/Antenne · Stereoanlage/Tuner', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p120', 'allemand', '3AS', 15, 120, 'L6 3AS p120 — Relativsätze (Genitiv) + Relativpronomen-Tabelle + Was passt zusammen + Kommunikationsmedien', E'2. Ergänzen Sie Relativsätze.\n- Heute Abend läuft ein Film, ………… Geschichte authentisch ist.\n- Ich habe einen Dvd-Player gekauft, ………… Preis interessant war.\n- In dieser Abteilung arbeiten drei Techniker, ………… Namen ich nicht kenne.\n- Ich will mir einen Computer kaufen, ………… Bildschirm groß ist.\n- Gestern habe ich eine wissenschaftliche Sendung gesehen, ………… Inhalt interessant war.\n3. Ergänzen Sie die Tabelle. (Maskulinum/Neutrum/Femininum/Plural × Nominativ/Akkusativ/Dativ/Genitiv : der · das · der · deren)\n4. Was passt zusammen ?\n1. Ist das das Mädchen, · 2. Sind das die Kinder, · 3. Ist das die Künstlerin, · 4. Ist das der Ingenieur, · 5. Ist das der Computer, · 6. Sind das die Programme, · 7. Ist das der Absender, · 8. Sind das die Schüler, · 9. Sind das die Arbeiter,\na) der dieses Gerät repariert hat ? · b) der du SMS verschickst ? · c) denen du Computerspiele geschenkt hast ? · d) dem du E Mails sendest ? · e) die sich für das Internet interessieren? · f) der dir ein Paket geschickt hat ? · g) deren Fabrik geschlossen wurde ? · h) den du regelmäßig benutzt ? · i) die du zu Hause benutzt ?\n(Lösungstabelle : 1 → d)\n5. Welcher Satz passt zu welchem Kommunikationsmedium ?\n1. Du Lisa, ich liege gerade am Strand. Ich wollte dir sagen… · 2. Hier spricht der automatische Anrufbeantworter von Lisa… · 3. Liebe Lisa, es tut mir so leid, dass ich dir nicht geantwortet habe. · 4. Hi, Lisa, hast du Lust, heute Abend ins Kino zu gehen ? · 5. Liebe Frau Meier, vielen Dank für Ihr Schreiben… · 6. Ja, hallo, hier ist Paul, ich wollte dich nur fragen, ob du zu Hause bist.\nSMS · Brief · Handy · Fax · Telefon · E-Mail', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
